import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("rounds half-cent ties to the even cent so invoices don't drift upward", () => {
    expect(roundCents(12.5)).toBe(12);
    expect(roundCents(13.5)).toBe(14);
    expect(roundCents(0.5)).toBe(0);
  });

  it("rounds non-tie amounts to the nearest cent", () => {
    expect(roundCents(12.49)).toBe(12);
    expect(roundCents(12.51)).toBe(13);
    expect(roundCents(100)).toBe(100);
  });

  it("treats refunds (negative amounts) symmetrically", () => {
    expect(roundCents(-12.5)).toBe(-12);
    expect(roundCents(-13.5)).toBe(-14);
    expect(roundCents(-12.51)).toBe(-13);
  });

  it("rejects non-finite amounts instead of billing NaN", () => {
    expect(() => roundCents(NaN)).toThrow(RangeError);
    expect(() => roundCents(Infinity)).toThrow(RangeError);
  });
});

